class ChandrasekharSieve:
    def __init__(self, n):
        self.n = n
        self.primes = self.generate_primes()
    def generate_primes(self):
        n = self.n
        if n < 2: return []
        primes = [2]
        if n < 3: return primes
        size = (n - 3) // 2 + 1
        is_prime = [True] * size
        for i in range(size):
            if is_prime[i]:
                p = 2 * i + 3
                if p * p > n: break
                start = (p * p - 3) // 2
                for j in range(start, size, p): is_prime[j] = False
        for i in range(size):
            if is_prime[i]: primes.append(2 * i + 3)
        return primes
    def get_primes(self):
        return self.primes
